{
  "gate_token": "jIbNyExhS476e9oAzrnZkQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept ridge at dusk overlooking a shattered skyline of broken spires; an ink-stained coat flaps as a brass compass spins above a parchment map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false paths ahead.",
      "visual_description": "A small oil lamp held aloft, its single flame-eye glowing amber, casting long warning shadows over the map's red-marked routes.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked outer wall.",
      "visual_description": "A clockwork fox with blue glass eyes crouches in rubble beside a collapsed gate, key-wind tail ticking softly under torn royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerges headfirst from a tall broken pane, coat shimmering with reflections of distant fires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They pass under the great castle gates.",
      "visual_description": "Massive iron-banded gates hang half-torn from hinges; four small figures slip beneath, dwarfed by carved stone lions.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp refuses the cursed tower.",
      "visual_description": "A leaning black tower wreathed in violet mist; the lamp's eye narrows to a slit, light pulling backward away from the doorway.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a winged beast echo from the rooftops.",
      "visual_description": "Silhouettes of enormous claw-marks gouged across tile roofs, a single scaled feather drifting down past the tin fox's twitching ears.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A plump official snoring on a ledger pillow inside a tilted toll booth, stamped papers stuck to his sleeves and cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara bribes a stamp from his limp hand.",
      "visual_description": "Mara delicately lifts a wax seal from sleeping fingers while the lamp tilts to illuminate the official's drooling smile.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "An armored patrol marches along a torchlit avenue.",
      "visual_description": "From a low alley, the tin fox watches plated boots and pike-shadows pass between fallen banner poles, brass eyes glinting.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver slips through a puddle into a mirrored hall.",
      "visual_description": "A coat-tail vanishing downward into a rain puddle, surfacing inside a long hall lined with cracked mirrors and tipped chandeliers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a true name.",
      "visual_description": "An ornate door inscribed with rotating sigils glows pale green; the oracle lamp hovers close, flame-eye flickering as it whispers.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox triggers the hidden latch.",
      "visual_description": "Small metal paws press a floor-tile rune; the door splits open in a spiral of light, illuminating four travelers at the threshold.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "They reach the captive in a sunken throne room.",
      "visual_description": "A figure curled inside a hanging glass cage above a cracked dais; the glass diver scales the cage from inside, hand pressed to the prisoner's.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Alarm bells wake the tax collector mid-snore.",
      "visual_description": "Tower bells ring red over the city; the official jolts upright in his booth, papers fluttering, ledger sliding from his lap.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The lamp lights a route through smoke.",
      "visual_description": "Thick black smoke curls through a courtyard of toppled statues; the lamp's flame-eye carves a narrow corridor of gold light forward.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the broken bridge at dawn.",
      "visual_description": "A long stone bridge crumbling into a river of mist; four small figures run as planks fall away behind them, pink sunrise ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "On the far shore, Mara marks the city as closed.",
      "visual_description": "A new map spread on a tree stump; a brass compass pins the corner while the tin fox curls asleep and the lamp dims to an ember.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    }
  ]
}

